files.content:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #1a1a2e;
  color: #e0e0e0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-container {
  background: #16213e;
  border: 4px solid #0f3460;
  border-radius: 12px;
  padding: 24px;
  max-width: 600px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
}

h1 {
  font-size: 1.75rem;
  color: #e94560;
  margin-bottom: 4px;
  letter-spacing: 1px;
}

.subtitle {
  font-size: 1rem;
  color: #a0a0b0;
  margin-bottom: 16px;
}

.turn-indicator {
  font-size: 1.25rem;
  font-weight: bold;
  padding: 12px;
  margin-bottom: 16px;
  background: #0f3460;
  border-radius: 8px;
  border: 2px solid #e94560;
}

.track {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 4px;
  margin-bottom: 20px;
}

.square {
  aspect-ratio: 1;
  background: #0f3460;
  border: 2px solid #1a1a2e;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  color: #a0a0b0;
  position: relative;
  flex-wrap: wrap;
  gap: 2px;
}

.square .token {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  display: inline-block;
}

.token.p1 {
  background: #e94560;
}

.token.p2 {
  background: #4ecca3;
}

.dice-area {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.dice {
  width: 64px;
  height: 64px;
  background: #e0e0e0;
  color: #1a1a2e;
  font-size: 2rem;
  font-weight: bold;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  border: 3px solid #0f3460;
  box-shadow: 0 4px 0 #0f3460;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  padding: 12px 24px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  min-width: 140px;
}

.btn.primary {
  background: #e94560;
  color: #fff;
  box-shadow: 0 4px 0 #a02a3f;
}

.btn.primary:hover {
  background: #ff5c77;
}

.btn.primary:active {
  transform: translateY(2px);
  box-shadow: 0 2px 0 #a02a3f;
}

.btn.secondary {
  background: #4ecca3;
  color: #1a1a2e;
  box-shadow: 0 4px 0 #2e8b6e;
  margin-top: 12px;
}

.btn.secondary:hover {
  background: #6ee7b7;
}

.btn.secondary:active {
  transform: translateY(2px);
  box-shadow: 0 2px 0 #2e8b6e;
}

.btn:focus-visible {
  outline: 3px solid #f0c040;
  outline-offset: 3px;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.winner-message {
  font-size: 1.5rem;
  font-weight: bold;
  color: #f0c040;
  padding: 16px;
  margin-bottom: 8px;
  background: #0f3460;
  border-radius: 8px;
  border: 2px solid #f0c040;
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .dice {
    width: 52px;
    height: 52px;
    font-size: 1.5rem;
  }
  .btn {
    padding: 10px 16px;
    min-width: 120px;
    font-size: 0.95rem;
  }
  .square {
    font-size: 0.65rem;
  }
  .square .token {
    width: 10px;
    height: 10px;
  }
}

(function () {
  'use strict';

  var TRACK_SIZE = 20;
  var state = {
    positions: [0, 0],
    currentPlayer: 0,
    gameOver: false
  };

  var trackEl = document.getElementById('track');
  var diceEl = document.getElementById('dice');
  var turnEl = document.getElementById('turnIndicator');
  var rollBtn = document.getElementById('rollBtn');
  var playAgainBtn = document.getElementById('playAgainBtn');
  var winnerEl = document.getElementById('winnerMessage');

  function buildTrack() {
    trackEl.innerHTML = '';
    for (var i = 1; i <= TRACK_SIZE; i++) {
      var sq = document.createElement('div');
      sq.className = 'square';
      sq.setAttribute('data-index', i);
      sq.setAttribute('aria-label', 'Square ' + i);
      var num = document.createElement('span');
      num.textContent = i;
      sq.appendChild(num);
      trackEl.appendChild(sq);
    }
    renderTokens();
  }

  function renderTokens() {
    var squares = trackEl.querySelectorAll('.square');
    for (var i = 0; i < squares.length; i++) {
      squares[i].querySelectorAll('.token').forEach(function (t) { t.remove(); });
    }
    for (var p = 0; p < 2; p++) {
      var pos = state.positions[p];
      if (pos > 0 && pos <= TRACK_SIZE) {
        var sq = squares[pos - 1];
        var token = document.createElement('span');
        token.className = 'token p' + (p + 1);
        token.setAttribute('aria-label', 'Player ' + (p + 1) + ' token');
        sq.appendChild(token);
      }
    }
  }

  function updateTurn() {
    if (state.gameOver) return;
    turnEl.textContent = 'Player ' + (state.currentPlayer + 1) + "'s turn";
  }

  function rollDice() {
    if (state.gameOver) return;
    var roll = Math.floor(Math.random() * 6) + 1;
    diceEl.textContent = roll;
    diceEl.setAttribute('aria-label', 'Dice showing ' + roll);

    var p = state.currentPlayer;
    state.positions[p] = Math.min(state.positions[p] + roll, TRACK_SIZE);
    renderTokens();

    if (state.positions[p] >= TRACK_SIZE) {
      state.gameOver = true;
      turnEl.textContent = 'Game Over';
      winnerEl.textContent = 'Player ' + (p + 1) + ' wins!';
      winnerEl.hidden = false;
      playAgainBtn.hidden = false;
      rollBtn.disabled = true;
      return;
    }

    state.currentPlayer = 1 - p;
    updateTurn();
  }

  function resetGame() {
    state.positions = [0, 0];
    state.currentPlayer = 0;
    state.gameOver = false;
    diceEl.textContent = '1';
    diceEl.setAttribute('aria-label', 'Dice showing 1');
    winnerEl.hidden = true;
    winnerEl.textContent = '';
    playAgainBtn.hidden = true;
    rollBtn.disabled = false;
    updateTurn();
    renderTokens();
  }

  rollBtn.addEventListener('click', rollDice);
  playAgainBtn.addEventListener('click', resetGame);

  buildTrack();
  updateTurn();
})();
